// Inactive, manual-only example. Replace every placeholder and select credentials on BOTH AWS nodes.
// Use the same durable upstream event ID and exact paths when retrying the same change.
const distributionId = 'REPLACE_DISTRIBUTION_ID';
const paths = '/REPLACE_WITH_REVIEWED_PATH';
const callerReference = 'REPLACE_WITH_STABLE_UPSTREAM_EVENT_ID';
const pollSeconds = 10;
const timeoutSeconds = 900;
if ([distributionId, paths, callerReference].some(value => value.includes('REPLACE_'))) {
  throw new Error('Configure distribution, reviewed paths and a stable upstream event reference before running.');
}
if (!distributionId || !paths || !callerReference || !Number.isInteger(pollSeconds) || pollSeconds < 1 || !Number.isInteger(timeoutSeconds) || timeoutSeconds < 1) {
  throw new Error('Invalid example configuration.');
}
const startedAt = Date.now();
return [{ json: { distributionId, paths, callerReference, pollSeconds, startedAt, deadline: startedAt + timeoutSeconds * 1000 } }];

// Single-request example: immutable request state survives Get output replacement and every Wait.
const request = $('Prepare Request').first(0, 0).json;
const created = $('Create Invalidation').first(0, 0).json;
const result = $input.first().json;
const state = { ...request, invalidationId: created.invalidationId ?? null, status: result.status ?? null };
if (result.error) {
  const safe = result.error;
  return [{ json: { ...state, outcome: 'error', error: { message: 'CloudFront operation failed', code: typeof safe.code === 'string' ? safe.code : 'CloudFrontError', ...(Number.isInteger(safe.httpStatus) ? { httpStatus: safe.httpStatus } : {}), ...(typeof safe.requestId === 'string' ? { requestId: safe.requestId } : {}) } } }];
}
if (Date.now() >= request.deadline) return [{ json: { ...state, outcome: 'timeout' } }];
if (typeof state.invalidationId !== 'string' || !state.invalidationId || result.invalidationId !== state.invalidationId || result.distributionId !== request.distributionId) {
  return [{ json: { ...state, outcome: 'error', error: { message: 'CloudFront response identity mismatch', code: 'UnexpectedResponse' } } }];
}
if (result.status === 'Completed') return [{ json: { ...state, outcome: 'completed', confirmedAt: new Date().toISOString() } }];
if (result.status === 'InProgress') return [{ json: { ...state, outcome: 'poll' } }];
return [{ json: { ...state, outcome: 'error', error: { message: 'Unexpected CloudFront invalidation status', code: 'UnexpectedStatus' } } }];

const state = $input.first().json;
if (state.outcome !== 'completed' || state.status !== 'Completed') throw new Error('AWS completion was not confirmed.');
return [{ json: state }];
